def _canonical(value, policy='PACKAGE'):
    maximum, max_nodes, max_depth = _POLICIES[policy]
    nodes = 0
    charged = 0
    ancestors = set()
    def add(n):
        nonlocal charged
        charged += n
        if charged > maximum:
            _fail('INPUT_LIMIT')
    def visit(v, depth):
        nonlocal nodes
        nodes += 1
        if nodes > max_nodes or depth > max_depth:
            _fail('INPUT_LIMIT')
        t = type(v)
        if v is None:
            add(4)
            return 'null'
        if t is bool:
            add(4 if v else 5)
            return 'true' if v else 'false'
        if t is int:
            if abs(v) > 9007199254740991:
                _fail('INVALID_INPUT')
            text = str(v)
            add(len(text))
            return text
        if t is str:
            if len(v) > 2000000:
                _fail('INPUT_LIMIT')
            if _SURROGATE.search(v):
                _fail('INVALID_INPUT')
            text = encode_basestring(v)
            add(len(text.encode('utf8')))
            return text
        if t not in (dict, list) or id(v) in ancestors:
            _fail('INVALID_INPUT')
        if len(v) > 32768:
            _fail('INPUT_LIMIT')
        if t is dict and any(type(k) is not str for k in v):
            _fail('INVALID_INPUT')
        ancestors.add(id(v))
        add(2 + max(0, len(v)-1) + (len(v) if t is dict else 0))
        if t is list:
            text = '[' + ','.join(visit(x, depth+1) for x in v) + ']'
        else:
            text = '{' + ','.join(visit(k, depth+1)+':'+visit(v[k], depth+1) for k in sorted(v)) + '}'
        ancestors.remove(id(v))
        return text
    return visit(value, 0)

def _detach(v, policy):
    return json.loads(_canonical(v, policy))
def _clone(v):
    return json.loads(_canonical(v))
def _hash(v):
    return hashlib.sha256(_canonical(v).encode('utf8')).hexdigest()
def _eq(a, b):
    return _canonical(a) == _canonical(b)
def _omit(v, keys):
    return {k: x for k, x in v.items() if k not in keys}
def _exact(v, keys):
    return type(v) is dict and len(v) == len(keys) and all(k in v for k in keys)

