_OPERATIONAL = frozenset(('PAIR_REVIEW_UNAPPROVED','SOURCE_REVIEW_UNVERIFIED','SOURCE_SECTION_UNVERIFIED','SOURCE_STAGE_UNVERIFIED','SOURCE_LINK_UNVERIFIED',
    'PHYSICAL_MEMBER_UNVERIFIED','SECTION_SHAPE_UNVERIFIED','DIMENSION_MEANING_UNVERIFIED','UNIT_UNVERIFIED','PAIR_APPLICABILITY_UNVERIFIED'))
